# owner: platform
import unittest

from rosterkit.contacts import contact_sheet
from rosterkit.errors import ProjectError
from rosterkit.models import Student

# ---
def make_student(
    last, first, section="A", email="x@y.test"
):
    return Student("id", last, first, section, email)

class ContactSheetTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_sheet([
            make_student("Zane", "Amy"),
            make_student("Adams", "Bob")
        ])
        self.assertTrue(rows[0].startswith("Adams, Bob"))
        self.assertTrue(rows[1].startswith("Zane, Amy"))

    def test_columns_line_up(self):
        rows = contact_sheet([
            make_student("Adams", "Bob", "A", "bob@s.test"),
            make_student("Longername", "Cy", "B", "cy@s.t")
        ])
        self.assertEqual(
            rows[0].index("bob@s.test"),
            rows[1].index("cy@s.t")
        )
        self.assertIn("A", rows[0][20:30])

    def test_missing_email_names_student(self):
        with self.assertRaises(ProjectError) as caught:
            contact_sheet([
                make_student("Adams", "Bob", email=None)
            ])
        self.assertIn("Adams, Bob", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_sheet([])

if __name__ == "__main__":
    unittest.main()
